    int dc[4] = {0, 1, 0, -1};

    // Start at (0,0) facing east (to have wall on right = south)
    int r = 0, c = 0, dir = 1; 
    int start_r = r, start_c = c, start_dir = dir;

    // We'll store moves as characters
    char path[10000];
