        int nc = c + dc[right_dir];
        int can_right = 1;
        // Check wall on right side
        if (right_dir == 0 && (r == 0 || h[r-1][c])) can_right = 0;
        if (right_dir == 1 && (c == n-1 || v[r][c+1])) can_right = 0;
        if (right_dir == 2 && (r == n-1 || h[r][c])) can_right = 0;
        if (right_dir == 3 && (c == 0 || v[r][c])) can_right = 0;

        if (can_right) {
            dir = right_dir;
            path[path_len++] = 'R';
        } else {
            // Try to go straight
            int nr = r + dr[dir];
            int nc = c + dc[dir];
            int can_straight = 1;
            if (dir == 0 && (r == 0 || h[r-1][c])) can_straight = 0;
            if (dir == 1 && (c == n-1 || v[r][c+1])) can_straight = 0;
            if (dir == 2 && (r == n-1 || h[r][c])) can_straight = 0;
            if (dir == 3 && (c == 0 || v[r][c])) can_straight = 0;

            if (can_straight) {
                path[path_len++] = 'S';
            } else {
                // Turn left
                dir = (dir + 3) % 4;
                path[path_len++] = 'L';
                continue;
            }
        }
        // Move forward
        r += dr[dir];
        c += dc[dir];

