#define MAXN 205

/* 
   Right-hand rule on a square grid.

   Input format assumed:
   N
   top edge bits
   right edge bits
   bottom edge bits
   left edge bits

   Each edge bit string has length N.

   We model the boundary walls on an N x N cell grid:
   - top[j]    : wall between outside and cell (0,j) on its north side
   - right[i]  : wall between outside and cell (i,N-1) on its east side
   - bottom[j] : wall between outside and cell (N-1,j) on its south side
   - left[i]   : wall between outside and cell (i,0) on its west side

   Start point A is the northwest outer corner of the square, facing east.
   We walk along grid lines, keeping the wall on the right, until returning to A
   with the initial direction.

   Output:
   sequence of moves using E, S, W, N
*/

static int N;
static char topEdge[MAXN], rightEdge[MAXN], bottomEdge[MAXN], leftEdge[MAXN];

/* Directions: 0=E,1=S,2=W,3=N */
static const int dx[4] = {1, 0, -1, 0};
static const int dy[4] = {0, 1, 0, -1};
static const char dc[4] = {'E', 'S', 'W', 'N'};

/* 
   Determine whether the unit segment from vertex (x,y) to (x+dx[d], y+dy[d])
   has a wall immediately on its right side.
   Vertices are on 0..N x 0..N.
*/
int wall_on_right(int x, int y, int d) {
    if (d == 0) { /* moving east, right side is south */
        if (y >= N) return 0;
        if (y == N - 1) {
            if (x >= 0 && x < N) return bottomEdge[x] == '1';
        }
        return 0;
    } else if (d == 1) { /* moving south, right side is west */
        if (x <= 0) {
            if (y >= 0 && y < N) return leftEdge[y] == '1';
        }
        return 0;
    } else if (d == 2) { /* moving west, right side is north */
        if (y <= 0) {
            if (x > 0 && x <= N) return topEdge[x - 1] == '1';
        }
        return 0;
    } else { /* moving north, right side is east */
        if (x == N) {
            if (y > 0 && y <= N) return rightEdge[y - 1] == '1';
        }
        return 0;
    }
}

/* Check if moving one step in direction d stays on the outer perimeter */
int can_move(int x, int y, int d) {
    int nx = x + dx[d], ny = y + dy[d];
    if (nx < 0 || nx > N || ny < 0 || ny > N) return 0;
    /* Must remain on perimeter */
    if (!(nx == 0 || nx == N || ny == 0 || ny == N)) return 0;
    return 1;
}

int main(void) {
    if (scanf("%d", &N) != 1) return 0;
    scanf("%s", topEdge);
    scanf("%s", rightEdge);
    scanf("%s", bottomEdge);
    scanf("%s", leftEdge);

    int x = 0, y = 0, dir = 0; /* start at A, facing east */

    char ans[100000];
    int len = 0;

    do {
        int cand[4] = {(dir + 1) % 4, dir, (dir + 3) % 4, (dir + 2) % 4};
        int chosen = -1;

        for (int i = 0; i < 4; i++) {
            int nd = cand[i];
            if (!can_move(x, y, nd)) continue;
            int nx = x + dx[nd], ny = y + dy[nd];
            if (wall_on_right(x, y, nd)) {
                chosen = nd;
                break;
            }
            /* also allow move if next segment after this keeps boundary continuity */
            if (i == 1 || i == 2 || i == 3) {
                chosen = nd;
                break;
            }
            (void)nx; (void)ny;
        }

        if (chosen == -1) break;

        ans[len++] = dc[chosen];
        x += dx[chosen];
        y += dy[chosen];
        dir = chosen;
    } while (!(x == 0 && y == 0 && dir == 0));

    ans[len] = '\0';
    printf("%s\n", ans);
    return 0;
}

