    cin >> h >> w;

    // Horizontal walls: h+1 rows, w columns
    vector<vector<int>> hwalls(h+1, vector<int>(w));
    for (int i = 0; i <= h; i++)
        for (int j = 0; j < w; j++)
            cin >> hwalls[i][j];

    // Vertical walls: h rows, w+1 columns
    vector<vector<int>> vwalls(h, vector<int>(w+1));
    for (int i = 0; i < h; i++)
        for (int j = 0; j <= w; j++)
            cin >> vwalls[i][j];

    // Directions: 0=right, 1=down, 2=left, 3=up
    int dx[4] = {0, 1, 0, -1};
    int dy[4] = {1, 0, -1, 0};

    int x = 0, y = 0, dir = 0; // start at (0,0) facing right

    // Store path
    vector<pair<int,int>> path;
    path.emplace_back(x, y);

    do {
        // Try to turn right
        int rightDir = (dir + 1) % 4;
        int nx = x + dx[rightDir];
        int ny = y + dy[rightDir];

        bool canMoveRight = false;
        if (nx >= 0 && nx < h && ny >= 0 && ny < w) {
            // Check wall between current and right cell
            if (rightDir == 0) { // moving right -> check vertical wall at (x, y+1)
                if (!vwalls[x][y+1]) canMoveRight = true;
            } else if (rightDir == 1) { // moving down -> check horizontal wall at (x+1, y)
                if (!hwalls[x+1][y]) canMoveRight = true;
            } else if (rightDir == 2) { // moving left -> check vertical wall at (x, y)
                if (!vwalls[x][y]) canMoveRight = true;
            } else if (rightDir == 3) { // moving up -> check horizontal wall at (x, y)
                if (!hwalls[x][y]) canMoveRight = true;
            }
        }

        if (canMoveRight) {
            dir = rightDir;
            x = nx;
            y = ny;
        } else {
            // Try moving forward
            int fx = x + dx[dir];
            int fy = y + dy[dir];
            bool canMoveForward = false;
            if (fx >= 0 && fx < h && fy >= 0 && fy < w) {
                if (dir == 0) {
                    if (!vwalls[x][y+1]) canMoveForward = true;
                } else if (dir == 1) {
                    if (!hwalls[x+1][y]) canMoveForward = true;
                } else if (dir == 2) {
                    if (!vwalls[x][y]) canMoveForward = true;
                } else if (dir == 3) {
                    if (!hwalls[x][y]) canMoveForward = true;
                }
            }
            if (canMoveForward) {
                x = fx;
                y = fy;
            } else {
                // Turn left until we can move forward
                for (int turn = 0; turn < 4; turn++) {
                    dir = (dir + 3) % 4; // turn left
                    int tx = x + dx[dir];
                    int ty = y + dy[dir];
                    if (tx >= 0 && tx < h && ty >= 0 && ty < w) {
                        bool canMove = false;
                        if (dir == 0) {
                            if (!vwalls[x][y+1]) canMove = true;
                        } else if (dir == 1) {
                            if (!hwalls[x+1][y]) canMove = true;
                        } else if (dir == 2) {
                            if (!vwalls[x][y]) canMove = true;
                        } else if (dir == 3) {
                            if (!hwalls[x][y]) canMove = true;
                        }
                        if (canMove) {
                            x = tx;
                            y = ty;
                            break;
                        }
                    }
                }
            }
        }
        path.emplace_back(x, y);
    } while (!(x == 0 && y == 0 && dir == 0));

    // Output path
    for (auto &p : path) {
        cout << p.first << " " << p.second << "\n";
    }

    return 0;
}

