import java.util.*;

public class RightHandWallFollower {
    static final int[] dr = {0, 1, 0, -1}; // right, down, left, up
    static final int[] dc = {1, 0, -1, 0};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        sc.nextLine();

        char[][] grid = new char[H][W];
        int startR = -1, startC = -1;

        for (int i = 0; i < H; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == 'A') {
                    startR = i;
                    startC = j;
                }
            }
        }

        int dir = 0; // 0: right, 1: down, 2: left, 3: up
        int r = startR, c = startC;
        List<String> path = new ArrayList<>();
        path.add((r + 1) + " " + (c + 1));

        do {
            int rightDir = (dir + 1) % 4;
            int nr = r + dr[rightDir];
            int nc = c + dc[rightDir];

            if (isValid(nr, nc, H, W) && grid[nr][nc] != '1') {
                // Turn right and move
                dir = rightDir;
                r = nr;
                c = nc;
            } else {
                int frontDir = dir;
                nr = r + dr[frontDir];
                nc = c + dc[frontDir];

                if (isValid(nr, nc, H, W) && grid[nr][nc] != '1') {
                    // Move forward
                    r = nr;
                    c = nc;
                } else {
                    // Turn left
                    dir = (dir + 3) % 4;
                }
            }
            path.add((r + 1) + " " + (c + 1));
        } while (!(r == startR && c == startC));

        for (String step : path) {
            System.out.println(step);
        }
    }

    static boolean isValid(int r, int c, int H, int W) {
        return r >= 0 && r < H && c >= 0 && c < W;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int n;
    static boolean[][] hWall; // horizontal walls: between (r,c) and (r,c+1), 0<=r<=n, 0<=c<n
    static boolean[][] vWall; // vertical walls: between (r,c) and (r+1,c), 0<=r<n, 0<=c<=n

    // directions: 0=E,1=S,2=W,3=N
    static int[] dr = {0, 1, 0, -1};
    static int[] dc = {1, 0, -1, 0};
    static char[] moveChar = {'R', 'D', 'L', 'U'};

    static boolean canMove(int r, int c, int dir) {
        int nr = r + dr[dir];
        int nc = c + dc[dir];
        if (nr < 0 || nr > n || nc < 0 || nc > n) return false;

        if (dir == 0) { // E
            return !hWall[r][c];
        } else if (dir == 2) { // W
            return !hWall[r][c - 1];
        } else if (dir == 1) { // S
            return !vWall[r][c];
        } else { // N
            return !vWall[r - 1][c];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;
        n = Integer.parseInt(first);

        hWall = new boolean[n + 1][n];
        vWall = new boolean[n][n + 1];

        // Input format assumed:
        // n+1 lines of horizontal wall strings of length n
        // n lines of vertical wall strings of length n+1
        for (int i = 0; i <= n; i++) {
            String s = fs.next();
            while (s.length() < n) s += fs.next();
            for (int j = 0; j < n; j++) hWall[i][j] = s.charAt(j) == '1';
        }
        for (int i = 0; i < n; i++) {
            String s = fs.next();
            while (s.length() < n + 1) s += fs.next();
            for (int j = 0; j <= n; j++) vWall[i][j] = s.charAt(j) == '1';
        }

        // Start at A = top-left corner (0,0), initially heading east.
        int sr = 0, sc = 0, sdir = 0;
        int r = sr, c = sc, dir = sdir;

        StringBuilder ans = new StringBuilder();

        // Right-hand rule traversal on vertex graph.
        // At each step, try right, straight, left, back.
        // Stop when we return to initial state after at least one move.
        boolean firstStep = true;
        while (firstStep || r != sr || c != sc || dir != sdir) {
            firstStep = false;

            int[] order = {(dir + 1) % 4, dir, (dir + 3) % 4, (dir + 2) % 4};
            int ndir = -1;
            for (int d : order) {
                if (canMove(r, c, d)) {
                    ndir = d;
                    break;
                }
            }

            if (ndir == -1) break; // isolated, should not happen

            ans.append(moveChar[ndir]);
            r += dr[ndir];
            c += dc[ndir];
            dir = ndir;
        }

        System.out.println(ans.toString());
    }
}
